import Link from './Link'
import siteMetadata from '@/data/siteMetadata'
import { Locale } from '@/data/i18n'
import { dictionary } from '@/data/dictionary'

// Both PDFs are generated by scripts/generate-cv.py.
const cvPaths: Record<Locale, string> = {
  en: siteMetadata.cvPath,
  zh: '/static/files/chien-yin-wu-cv-zh.pdf',
}

export default function CVDownload({
  className,
  label,
  locale = 'en',
}: {
  className?: string
  label?: string
  locale?: Locale
}) {
  const t = dictionary[locale].links
  return (
    <Link
      href={`${process.env.BASE_PATH || ''}${cvPaths[locale]}`}
      download={t.cvDownloadName}
      className={className}
    >
      {label ?? t.downloadCv}
    </Link>
  )
}
